package com.guangyingruoshui.imagetools;
import java.io.*;
final class VideoMetadata {
 static File clean(File input,File folder,Files.Job job)throws Exception{
  String name=input.getName(),ext=name.substring(name.lastIndexOf('.')+1).toLowerCase(java.util.Locale.ROOT);if(!("mp4 mov m4v webm mkv".contains(ext)&&java.util.Arrays.asList("mp4","mov","m4v","webm","mkv").contains(ext)))throw new IOException("视频支持 MP4 / MOV / M4V / WebM / MKV。");File out=Files.unique(folder,Files.stem(name)+"_已清信息."+ext),tmp=Files.temp(folder);
  try{Files.space(folder,input.length());try(InputStream in=new FileInputStream(input);OutputStream target=new FileOutputStream(tmp)){Files.copy(in,target,job);}try(RandomAccessFile f=new RandomAccessFile(tmp,"rw")){if(ext.equals("webm")||ext.equals("mkv"))ebml(f,job);else{if(f.length()<16||!type(f,4).equals("ftyp"))throw new IOException("无效 MP4/MOV 文件头。");boolean[] flags=new boolean[2];boxes(f,0,f.length(),0,job,flags);if(!flags[0]||!flags[1])throw new IOException("视频缺少媒体数据或轨道结构。");}}Files.commit(tmp,out,job);return out;}finally{tmp.delete();}
 }
 static long uint(RandomAccessFile f,long p,int n)throws Exception{f.seek(p);long v=0;for(int i=0;i<n;i++)v=v<<8|f.readUnsignedByte();if(v<0)throw new IOException("无效视频长度。");return v;}
 static String type(RandomAccessFile f,long p)throws Exception{f.seek(p);byte[] b=new byte[4];f.readFully(b);return new String(b,Files.LATIN);}
 static void zero(RandomAccessFile f,long p,long length,Files.Job j)throws Exception{f.seek(p);byte[] b=new byte[65536];while(length>0){j.check();int n=(int)Math.min(length,b.length);f.write(b,0,n);length-=n;}}
 static void boxes(RandomAccessFile f,long start,long end,int depth,Files.Job job,boolean[] flags)throws Exception{if(depth>16)throw new IOException("视频容器嵌套过深。");for(long p=start;p<end;){job.check();if(end-p<8)throw new IOException("视频数据块被截断。");long size=uint(f,p,4);String t=type(f,p+4);int head=8;if(size==1){if(end-p<16)throw new IOException("视频扩展长度被截断。");size=uint(f,p+8,8);head=16;}if(size==0)size=end-p;if(size<head||size>end-p)throw new IOException("视频数据块长度无效。");long next=p+size;boolean erase=t.equals("udta")||t.equals("meta");if(t.equals("uuid")&&size>=head+16){f.seek(p+head);byte[] id=new byte[16];f.readFully(id);byte[] xmp={(byte)0xbe,0x7a,(byte)0xcf,(byte)0xcb,(byte)0x97,(byte)0xa9,0x42,(byte)0xe8,(byte)0x9c,0x71,(byte)0x99,(byte)0x94,(byte)0x91,(byte)0xe3,(byte)0xaf,(byte)0xac};erase=java.util.Arrays.equals(id,xmp);}
  if(erase){f.seek(p+4);f.write("free".getBytes(Files.LATIN));zero(f,p+head,size-head,job);}else if(java.util.Arrays.asList("moov","trak","mdia","minf","stbl","edts","mvex","moof","traf").contains(t)){if(t.equals("moov"))flags[1]=true;boxes(f,p+head,next,depth+1,job,flags);}else if(t.equals("mvhd")||t.equals("tkhd")||t.equals("mdhd")){int v=(int)uint(f,p+head,1),dates=v==0?8:v==1?16:0;if(dates==0||size<head+4+dates)throw new IOException("视频时间信息无效。");zero(f,p+head+4,dates,job);}if(t.equals("pssh"))throw new IOException("不支持加密视频容器 / Encrypted video is unsupported");if(t.equals("stsd")){if(size<head+8)throw new IOException("视频样本描述无效 / Invalid sample descriptions");long entry=p+head+8,count=uint(f,p+head+4,4);if(count>(next-entry)/8)throw new IOException("视频样本描述无效 / Invalid sample descriptions");for(long n=0;n<count;n++){long length=uint(f,entry,4);if(length<8||length>next-entry)throw new IOException("视频样本描述无效 / Invalid sample descriptions");String format=type(f,entry+4);if(format.equals("encv")||format.equals("enca"))throw new IOException("不支持加密视频容器 / Encrypted video is unsupported");entry+=length;}}if(t.equals("mdat"))flags[0]=true;p=next;}}
 static class Element{long start,data,end,id;}
 static long vint(RandomAccessFile f,long[] p,int max,boolean id)throws Exception{int first=(int)uint(f,p[0]++,1),mask=128,n=1;while((first&mask)==0&&n<=max){mask>>=1;n++;}if(n>max||mask==0)throw new IOException("无效 EBML 长度。");long v=id?first:first&(mask-1);for(int i=1;i<n;i++)v=v<<8|uint(f,p[0]++,1);return !id&&v==((1L<<(7*n))-1)?-1:v;}
 static Element element(RandomAccessFile f,long start,long end)throws Exception{long[] p={start};long id=vint(f,p,4,true),size=vint(f,p,8,false);if(p[0]>end||(size>=0&&size>end-p[0])||(size<0&&id!=0x18538067))throw new IOException("视频 EBML 数据块无效。");Element e=new Element();e.start=start;e.data=p[0];e.end=size<0?end:p[0]+size;e.id=id;return e;}
 static void blank(RandomAccessFile f,Element e,Files.Job j)throws Exception{long total=e.end-e.start;int w=1;while(w<8&&total-1-w>=((1L<<(7*w))-1))w++;long payload=total-1-w;if(payload<0)throw new IOException("元数据块过短。");byte[] size=new byte[w];long v=payload;for(int i=w-1;i>=0;i--){size[i]=(byte)v;v>>>=8;}size[0]|=(byte)(1<<(8-w));f.seek(e.start);f.writeByte(0xec);f.write(size);zero(f,e.start+1+w,payload,j);}
 static void ebml(RandomAccessFile f,Files.Job job)throws Exception{if(f.length()<8||uint(f,0,4)!=0x1a45dfa3)throw new IOException("无效 WebM/MKV 文件头。");boolean found=false;for(long p=0;p<f.length();){job.check();Element e=element(f,p,f.length());if(e.id==0x18538067){found=true;for(long q=e.data;q<e.end;){job.check();Element c=element(f,q,e.end);if(c.id==0x1254c367||c.id==0x1941a469)blank(f,c,job);else if(c.id==0x1549a966){for(long a=c.data;a<c.end;){Element info=element(f,a,c.end);if(info.id==0x7ba9||info.id==0x4d80||info.id==0x5741||info.id==0x4461)blank(f,info,job);a=info.end;}}q=c.end;}}p=e.end;}if(!found)throw new IOException("视频缺少 EBML Segment。");}
}
